mapper.select:
select package_id, package_name, status, create_by, create_time, update_by, update_time, remark
from biz_crowd_package
where package_id = #{packageId}



    and p.package_name like concat('%', #{packageName}, '%')
    and p.status = #{status}

order by p.package_id desc

mapper.insert:
insert into biz_crowd_package (
    package_name, status, create_by, create_time, remark
) values (
    #{packageName}, #{status}, #{createBy}, sysdate(), #{remark}
)

mapper.update:
update biz_crowd_package
package_name = #{packageName}, status = #{status}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
where package_id = #{packageId}
